    """
    update the position VA
    """
    pos = {}
    if axes_to_update is None:
        axes_to_update = range(len(self._axes_names))
    for i in axes_to_update:
        pos[self._axes_names[i]] = self.GetAxisParam(i, 1) * self._ustepsize[i]

